import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse('{"title":"Start and follow your first analysis","description":"Start a full-project analysis, understand its states, and keep following it after a page refresh.","frontmatter":{"page_id":"guide-follow-a-run","description":"Start a full-project analysis, understand its states, and keep following it after a page refresh."},"headers":[],"relativePath":"en/guide/follow-a-run.md","filePath":"en/guide/follow-a-run.md","lastUpdated":1786290726000}'),o={name:"en/guide/follow-a-run.md"};function s(i,e,l,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="start-and-follow-your-first-analysis" tabindex="-1">Start and follow your first analysis <a class="header-anchor" href="#start-and-follow-your-first-analysis" aria-label="Permalink to &quot;Start and follow your first analysis&quot;">​</a></h1><p>Repository analysis is a background job. The API creates a run, the Worker takes it from the queue, and the frontend displays its current snapshot and later events. This page explains how to tell whether work is advancing and what to inspect at the end.</p><h2 id="check-before-starting" tabindex="-1">Check before starting <a class="header-anchor" href="#check-before-starting" aria-label="Permalink to &quot;Check before starting&quot;">​</a></h2><p>Before the first run, make sure that:</p><ul><li>the project has at least one active repository;</li><li>an enabled large language model (LLM) channel is available;</li><li>the API and Worker use the same database settings;</li><li>the Worker process is running; and</li><li>any private remote repository has a usable credential.</li></ul><p>If the Worker is not running, the API may still create the run, but it will remain in the queue.</p><h2 id="step-1-use-full-project-scope" tabindex="-1">Step 1: Use full-project scope <a class="header-anchor" href="#step-1-use-full-project-scope" aria-label="Permalink to &quot;Step 1: Use full-project scope&quot;">​</a></h2><p>Open the project&#39;s <strong>Runs</strong> page and choose <strong>New run</strong>.</p><p>For the first run, use:</p><ul><li>type: <strong>Full project</strong> (<code>full_project</code>);</li><li>repository scope: <strong>all active repositories</strong>;</li><li>branch: leave empty for repository defaults, or enter a branch you know exists;</li><li>LLM channel: keep the project default or select another enabled channel;</li><li>embedding channel: select a separate enabled channel when you need a semantic index; and</li><li>parallel processing: leave disabled when unsure, which uses a repository parallelism of <code>1</code>.</li></ul><p>Until a baseline exists, the backend permits only a full-project run and requires every active repository. The frontend shows a baseline notice and locks the repository scope.</p><p>Choose <strong>New run</strong>. The record appears at the top of the list. Any of <code>queued</code>, <code>running</code>, <code>scanning</code>, <code>analyzing</code>, or <code>finalizing</code> means that the run is still active.</p><h2 id="step-2-confirm-that-the-worker-advances-the-run" tabindex="-1">Step 2: Confirm that the Worker advances the run <a class="header-anchor" href="#step-2-confirm-that-the-worker-advances-the-run" aria-label="Permalink to &quot;Step 2: Confirm that the Worker advances the run&quot;">​</a></h2><p>While any run is active, the list refreshes about every five seconds. Open the run detail to see the persisted snapshot, timeline, analysis blocks, tool calls, and usage that are available at its current stage.</p><p>If the run remains <code>queued</code> for a long time:</p><ol><li>Check that the Worker terminal is still running.</li><li>Confirm that the Worker and API read the same database and related key settings.</li><li>Inspect the current Worker error instead of creating repeated runs.</li></ol><p>A useful intermediate result is a transition from <code>queued</code> into scanning, analysis, or finalization, together with new timeline content on the detail page.</p><h2 id="step-3-refresh-without-losing-progress" tabindex="-1">Step 3: Refresh without losing progress <a class="header-anchor" href="#step-3-refresh-without-losing-progress" aria-label="Permalink to &quot;Step 3: Refresh without losing progress&quot;">​</a></h2><p>When an active run is opened, the frontend first loads its current snapshot and then receives events after the snapshot cursor. You can refresh the browser or return to the same run later without replaying its earliest output.</p><p>After a successful refresh, you should see:</p><ul><li>the same run identifier;</li><li>the analysis content already persisted; and</li><li>new events continuing after the current cursor, without a second run being created.</li></ul><p>The browser event stream is not the job itself. Closing the page does not cancel the Worker run.</p><h2 id="step-4-decide-whether-the-run-is-complete" tabindex="-1">Step 4: Decide whether the run is complete <a class="header-anchor" href="#step-4-decide-whether-the-run-is-complete" aria-label="Permalink to &quot;Step 4: Decide whether the run is complete&quot;">​</a></h2><p>Terminal states are:</p><ul><li><code>completed</code>: the run completed;</li><li><code>completed_with_warnings</code>: the run completed with warnings to inspect;</li><li><code>failed</code>: the run failed; and</li><li><code>cancelled</code>: the run was cancelled.</li></ul><p>For a completed run, including one with warnings, the frontend loads the final result directly and does not keep an event-stream connection open. The detail page can show the final process text, analysis blocks, usage, warnings, and documents produced by that run.</p><p>Verify that:</p><ol><li>The state is <code>completed</code> or <code>completed_with_warnings</code>.</li><li>The detail page shows a final result instead of waiting for more events.</li><li>The document area lists the documents that were actually produced.</li><li>The search-index status matches your expectation. If it is <code>degraded</code> or <code>unavailable</code>, read the warning instead of treating it as a complete semantic index.</li></ol><p><code>completed_with_warnings</code> is not an unconditional success. You can use the results that exist, but first identify any repository, document, or index that did not complete.</p><h2 id="cancel-and-retry" tabindex="-1">Cancel and retry <a class="header-anchor" href="#cancel-and-retry" aria-label="Permalink to &quot;Cancel and retry&quot;">​</a></h2><p>A user with project management access can cancel an active run. After the request completes, the state becomes <code>cancelled</code>. Closing the page alone never cancels it.</p><p>The retry action on a terminal run creates a new run record. Follow the new record; the old one does not return to an active state.</p><p>Once documents exist, continue with <a href="./read-search-chat">reading documents, searching the project, and asking questions</a>.</p>',33)])])}const f=t(o,[["render",s]]);export{p as __pageData,f as default};
